const KEYS={posts:"my-aliyah-posts-v1",settings:"my-aliyah-settings-v1",journal:"my-aliyah-journal-v1",legacyPosts:"just-mine-posts-v1",olderPosts:"innercircle-demo-posts-v2",legacySettings:"just-mine-settings-v1",legacyJournal:"just-mine-journal-v1"};
const $=(s,r=document)=>r.querySelector(s),defaults={name:"Sarah",theme:"navy",setupComplete:false,pin:"",aliyahDate:""};
const prompts=["What felt most Israeli about today?","What surprised you about life in Israel today?","What small victory did you have today?","What do you miss, and what are you grateful for?","What Hebrew word or phrase did you use today?","What part of your aliyah journey do you want to remember?","What made Israel feel like home today?"];
const starterPost={id:"garden",text:"A small moment from my new life in Israel.",image:"assets/garden-post.jpg",mood:"Proud",createdAt:new Date().toISOString(),timestamp:"Today at 9:14 AM",saved:false};
function loadJson(k,f){try{return JSON.parse(localStorage.getItem(k))??f}catch{return f}}
function migrate(primary,legacy,fallback){const saved=loadJson(primary,null);if(saved!==null)return saved;const old=loadJson(legacy,null);return old!==null?old:fallback}
let settings={...defaults,...(loadJson(KEYS.settings,null)??loadJson(KEYS.legacySettings,null)??loadJson("innercircle-demo-settings-v2",defaults))};
const myAliyahPosts=loadJson(KEYS.posts,null),justMinePosts=loadJson(KEYS.legacyPosts,null),originalPosts=loadJson(KEYS.olderPosts,null),oldestPosts=loadJson("innercircle-demo-posts-v1",null);
let posts=Array.isArray(myAliyahPosts)&&myAliyahPosts.length?myAliyahPosts:Array.isArray(justMinePosts)&&justMinePosts.length?justMinePosts:Array.isArray(originalPosts)&&originalPosts.length?originalPosts:Array.isArray(oldestPosts)&&oldestPosts.length?oldestPosts:[];
posts=posts.map(p=>({...p,createdAt:p.createdAt||new Date().toISOString(),tag:p.tag||""}));
const myAliyahJournal=loadJson(KEYS.journal,null),justMineJournal=loadJson(KEYS.legacyJournal,null),originalJournal=loadJson("innercircle-demo-journal-v1",null);
let journalEntries=(Array.isArray(myAliyahJournal)&&myAliyahJournal.length?myAliyahJournal:Array.isArray(justMineJournal)&&justMineJournal.length?justMineJournal:Array.isArray(originalJournal)?originalJournal:[]).map(e=>({...e,createdAt:e.createdAt||new Date().toISOString()}));
let selectedImage="",selectedMood="",activeView="feed",editingJournalId="";
function persist(k,v){try{localStorage.setItem(k,JSON.stringify(v));return true}catch{showToast("Browser storage is full. Download a backup and remove older photos.");return false}}
const savePosts=()=>persist(KEYS.posts,posts),saveSettings=()=>persist(KEYS.settings,settings),saveJournal=()=>persist(KEYS.journal,journalEntries);
function esc(v=""){return String(v).replace(/[&<>'"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"}[c]))}
function firstName(){return(settings.name||"Friend").trim().split(/\s+/)[0]}
function applyTheme(){document.body.classList.toggle("theme-orange",settings.theme==="orange")}
function greeting(){const h=new Date().getHours();return h<12?"Good morning":h<18?"Good afternoon":"Good evening"}
function dateKey(v){const d=new Date(v);return`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`}
function readableDate(v){return new Date(v).toLocaleDateString([],{year:"numeric",month:"long",day:"numeric"})}
function journeyDay(){if(!settings.aliyahDate)return"";const start=new Date(`${settings.aliyahDate}T00:00:00`),today=new Date();const days=Math.floor((today-start)/86400000)+1;return days>0?`Day ${days.toLocaleString()} of your aliyah journey`:""}
function updateIdentity(){const initial=firstName().charAt(0).toUpperCase()||"F";document.querySelectorAll(".avatar-sarah").forEach(el=>el.textContent=initial);const chip=$(".profile-chip span:last-child");if(chip)chip.textContent=firstName();if(activeView==="feed"){$("#pageTitle").textContent=`${greeting()}, ${firstName()}`;$("#pageSubtitle").textContent=journeyDay()}}
function postCard(p,interactive=true){return`<article class="post card" data-id="${esc(p.id)}"><header class="post-head"><span class="avatar avatar-sarah">${esc(firstName().charAt(0))}</span><div><strong>${esc(firstName())}</strong><time>${esc(p.timestamp||readableDate(p.createdAt))}</time></div>${p.mood?`<span class="mood-label">Feeling ${esc(p.mood)}</span>`:""}</header><p class="post-text">${esc(p.text)}</p>${p.image?`<img class="post-image" src="${p.image}" alt="A photo from this aliyah journey">`:""}${interactive?`<div class="post-actions"><button class="post-action save-action ${p.saved?"saved":""}">${p.saved?"◆ Saved":"◇ Save memory"}</button><button class="post-action edit-action">Edit</button>${p.id!=="garden"?`<button class="post-action delete-action">Delete</button>`:""}</div>`:""}</article>`}
function renderFeed(list=posts){$("#feed").innerHTML=list.length?list.map(p=>postCard(p)).join(""):`<div class="card empty-state"><div class="empty-icon">◇</div><h2>Your journey starts here</h2><p>Share a thought or photo from your aliyah experience.</p></div>`;updateIdentity()}
function showToast(m){const t=$("#toast");t.textContent=m;t.classList.add("show");clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>t.classList.remove("show"),2500)}
function resetComposer(){$("#postText").value="";selectedImage="";selectedMood="";$("#photoInput").value="";$("#imagePreviewWrap").hidden=true;$("#selectedMood").hidden=true}
function todayPrompt(){return prompts[Math.floor(Date.now()/86400000)%prompts.length]}
function renderJournal(){const entries=journalEntries.map(e=>`<article class="journal-entry card" data-journal-id="${esc(e.id)}"><div class="journal-entry-head"><div><strong>${esc(e.title||"Untitled reflection")}</strong><time>${esc(e.date||readableDate(e.createdAt))}</time></div><div><button class="text-button journal-edit">Edit</button><button class="text-button journal-delete">Delete</button></div></div><p>${esc(e.body)}</p></article>`).join("");return`<section class="journal-composer card"><input id="journalTitle" maxlength="100" placeholder="Give this entry a title (optional)"><textarea id="journalBody" rows="8" maxlength="6000" placeholder="This page is yours…"></textarea><div class="journal-actions"><span>Private on this device</span><button id="saveJournalEntry" class="primary-button">Save journal entry</button></div></section><div class="journal-list">${entries||`<article class="card empty-state"><div class="empty-icon">▤</div><h2>Your journal is ready</h2><p>Your longer entries will appear here by date.</p></article>`}</div>`}
function onThisDayItems(){const n=new Date();return[...posts.map(p=>({...p,kind:"Post"})),...journalEntries.map(j=>({...j,text:j.body,kind:"Journal"}))].filter(i=>{const d=new Date(i.createdAt);return d.getMonth()===n.getMonth()&&d.getDate()===n.getDate()&&d.getFullYear()<n.getFullYear()})}
function renderMemories(){const old=onThisDayItems(),saved=posts.filter(p=>p.saved);return`${old.length?`<section class="memory-highlight card"><h2>On this day</h2><p>${old.length} ${old.length===1?"memory":"memories"} from years past</p></section>${old.map(p=>postCard(p,false)).join("")}`:""}${saved.length?`<div class="feed">${saved.map(p=>postCard(p,false)).join("")}</div>`:`<article class="card empty-state"><div class="empty-icon">◇</div><h2>No saved memories yet</h2><p>Choose “Save memory” beneath any post and it will appear here.</p></article>`}`}
function calendarResults(key){const items=[...posts.map(p=>({...p,kind:"Post"})),...journalEntries.map(j=>({...j,text:j.body,kind:"Journal"}))].filter(i=>dateKey(i.createdAt)===key);return items.length?items.map(i=>`<article class="calendar-item card"><strong>${i.kind}${i.title?` · ${esc(i.title)}`:""}</strong><p>${esc(i.text)}</p></article>`).join(""):`<article class="card empty-state"><p>Nothing was saved on this date.</p></article>`}
function renderCalendar(monthValue=dateKey(new Date()).slice(0,7),selected=""){const[year,month]=monthValue.split("-").map(Number),first=new Date(year,month-1,1),days=new Date(year,month,0).getDate(),counts={};[...posts,...journalEntries].forEach(i=>{const k=dateKey(i.createdAt);counts[k]=(counts[k]||0)+1});const blanks=Array(first.getDay()).fill('<div class="calendar-day empty"></div>').join(""),cells=Array.from({length:days},(_,i)=>{const k=`${monthValue}-${String(i+1).padStart(2,"0")}`,count=counts[k]||0;return`<button class="calendar-day ${count?"has-items":""} ${selected===k?"selected":""}" data-date="${k}">${i+1}${count?`<small>${count} ${count===1?"item":"items"}</small>`:""}</button>`}).join("");const opts=Array.from({length:24},(_,offset)=>{const d=new Date();d.setDate(1);d.setMonth(d.getMonth()-12+offset);const v=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}`;return`<option value="${v}" ${v===monthValue?"selected":""}>${d.toLocaleDateString([],{month:"long",year:"numeric"})}</option>`}).join("");return`<div class="calendar-toolbar card"><strong>Browse by date</strong><select id="calendarMonth">${opts}</select></div><div class="calendar-grid"><div class="calendar-weekday">Sun</div><div class="calendar-weekday">Mon</div><div class="calendar-weekday">Tue</div><div class="calendar-weekday">Wed</div><div class="calendar-weekday">Thu</div><div class="calendar-weekday">Fri</div><div class="calendar-weekday">Sat</div>${blanks}${cells}</div><div id="calendarResults" class="calendar-results">${selected?calendarResults(selected):""}</div>`}
function renderShipment(){
  const s=window.myAliyahShipment;
  if(!s)return `<article class="card empty-state"><div class="empty-icon">▣</div><h2>No shipment is connected yet</h2><p>When Aliyah Lift connects your account to its Airtable record, your dates, tracking and documents will appear here automatically.</p></article>`;
  const date=v=>v?new Date(v+"T00:00:00").toLocaleDateString([],{year:"numeric",month:"long",day:"numeric"}):"Not yet available";
  const link=(url,label,detail,icon)=>url?`<a class="portal-card" href="${esc(url)}" target="_blank" rel="noopener"><span class="portal-icon">${icon}</span><span><strong>${label}</strong><small>${detail}</small></span><b>›</b></a>`:"";
  return `<section class="shipment-overview card"><div><p class="eyebrow">Current status</p><h2>${esc(s.status||"Preparing")}</h2><p>Your Aliyah Lift shipment information.</p></div></section>
  <section class="shipment-details">
    <article class="card shipment-detail"><p class="detail-label">Shipment type</p><strong>${esc(s.shipment_type||"Not yet available")}</strong></article>
    <article class="card shipment-detail"><p class="detail-label">Packing date</p><strong>${date(s.packing_date)}</strong></article>
    <article class="card shipment-detail"><p class="detail-label">Estimated arrival</p><strong>${date(s.estimated_arrival)}</strong></article>
    <article class="card shipment-detail"><p class="detail-label">Container</p><strong>${esc(s.container_number||"Not yet available")}</strong></article>
    <article class="card shipment-detail"><p class="detail-label">Carrier</p><strong>${esc(s.carrier||"Not yet available")}</strong></article>
    <article class="card shipment-detail"><p class="detail-label">Volume</p><strong>${s.cubic_feet?esc(s.cubic_feet)+" cubic feet":"Not yet available"}</strong></article>
  </section>
  <h2 class="shipment-section-title">Shipment information</h2><section class="portal-actions">
    ${link(s.proposal_url,"Proposal","View your accepted proposal","▤")}
    ${link(s.invoice_url,"Invoice & payments","Review your invoice and payments","$")}
    ${link(s.tracking_url,"Track shipment","Open the shipping line’s tracking page","↗")}
  </section>`;
}
function renderSettings(){return`<article class="card settings-card"><div class="setting-block"><label>Your account</label><p>In the working app, you’ll be able to sign in on any device.</p><div class="signin-options"><button class="signin-button"><span class="signin-symbol apple">●</span>Continue with Apple</button><button class="signin-button"><span class="signin-symbol google">G</span>Continue with Google</button><button class="signin-button"><span class="signin-symbol email">@</span>Continue with email</button></div><small class="preview-label">Preview only — sign-in is not connected yet.</small></div><div class="setting-block"><label for="displayName">Your name</label><p>The greeting will use this name.</p><div class="name-row"><input id="displayName" maxlength="50" value="${esc(settings.name)}"><button id="saveName" class="primary-button">Save name</button></div></div><div class="setting-block"><label for="aliyahDate">Your aliyah date</label><p>Add the date you arrived in Israel to track your journey.</p><div class="name-row"><input id="aliyahDate" type="date" value="${esc(settings.aliyahDate)}"><button id="saveAliyahDate" class="primary-button">Save date</button></div></div><div class="setting-block"><label>Color theme</label><p>Choose the shade of Israeli blue you prefer.</p><div class="theme-options"><button class="theme-option ${settings.theme==="navy"?"active":""}" data-theme="navy"><span class="theme-swatch navy"></span>Deep Blue</button><button class="theme-option ${settings.theme==="orange"?"active":""}" data-theme="orange"><span class="theme-swatch orange"></span>Sky Blue</button></div></div><div class="setting-block"><label for="pinSetting">Privacy lock</label><p>Add a 4–8 digit PIN for this browser. This is a privacy screen, not encryption.</p><div class="name-row"><input id="pinSetting" class="pin-input" inputmode="numeric" maxlength="8" placeholder="${settings.pin?"PIN is set":"New PIN"}"><button id="savePin" class="primary-button">${settings.pin?"Change PIN":"Set PIN"}</button>${settings.pin?`<button id="removePin" class="secondary-button">Remove</button>`:""}</div></div><div class="setting-block"><label>Your data</label><p>Move your aliyah journal to another device or keep a safe copy.</p><div class="data-actions"><button id="exportData" class="secondary-button">Download backup</button><label class="import-label" for="importData">Restore backup</label><input id="importData" type="file" accept="application/json" hidden><button id="resetData" class="danger-button">Reset this browser</button></div></div></article>`}
const viewContent={memories:{title:"Aliyah memories",subtitle:"The moments you chose to keep.",render:renderMemories},journal:{title:"Aliyah journal",subtitle:"Write the longer story of your journey.",render:renderJournal},calendar:{title:"Journey calendar",subtitle:"See your aliyah story by date.",render:()=>renderCalendar()},shipment:{title:"My Shipment",subtitle:"Your Aliyah Lift shipment in one place.",render:renderShipment},settings:{title:"Settings",subtitle:"Personalize your aliyah journal.",render:renderSettings}};
function switchView(v){activeView=v;document.querySelectorAll(".nav-item").forEach(i=>i.classList.toggle("active",i.dataset.view===v));const feed=v==="feed";$("#feedView").classList.toggle("active-view",feed);$("#genericView").classList.toggle("active-view",!feed);if(feed)updateIdentity();else{const c=viewContent[v];$("#pageTitle").textContent=c.title;$("#pageSubtitle").textContent=c.subtitle;$("#genericView").innerHTML=c.render()}$(".sidebar").classList.remove("open")}
async function compressImage(file){const b=await createImageBitmap(file),max=1600,scale=Math.min(1,max/Math.max(b.width,b.height)),c=document.createElement("canvas");c.width=Math.round(b.width*scale);c.height=Math.round(b.height*scale);c.getContext("2d").drawImage(b,0,0,c.width,c.height);b.close();return c.toDataURL("image/jpeg",.76)}
$("#photoInput").addEventListener("change",async e=>{const f=e.target.files[0];if(!f)return;try{showToast("Preparing your photo…");selectedImage=await compressImage(f);$("#imagePreview").src=selectedImage;$("#imagePreviewWrap").hidden=false;showToast("Photo ready.")}catch{showToast("That photo could not be prepared.")}});
$("#removePhoto").addEventListener("click",()=>{selectedImage="";$("#photoInput").value="";$("#imagePreviewWrap").hidden=true});
$("#moodButton").addEventListener("click",()=>$("#moodModal").hidden=false);$("#closeMood").addEventListener("click",()=>$("#moodModal").hidden=true);$("#moodModal").addEventListener("click",e=>{if(e.target.id==="moodModal")e.currentTarget.hidden=true});document.querySelectorAll("[data-mood]").forEach(b=>b.addEventListener("click",()=>{selectedMood=b.dataset.mood;$("#selectedMood").textContent=selectedMood;$("#selectedMood").hidden=false;$("#moodModal").hidden=true}));
$("#postButton").addEventListener("click",()=>{const text=$("#postText").value.trim();if(!text&&!selectedImage)return showToast("Write something or add a photo first.");const now=new Date(),post={id:crypto.randomUUID(),text:text||"A moment from my aliyah journey.",image:selectedImage,mood:selectedMood,createdAt:now.toISOString(),timestamp:`Today at ${now.toLocaleTimeString([],{hour:"numeric",minute:"2-digit"})}`,saved:false};posts.unshift(post);if(savePosts()){renderFeed();resetComposer();showToast("Added to your aliyah journey.")}else posts.shift()});
$("#feed").addEventListener("click",e=>{const a=e.target.closest(".post");if(!a)return;const p=posts.find(i=>i.id===a.dataset.id);if(!p)return;if(e.target.closest(".save-action")){p.saved=!p.saved;savePosts();renderFeed();showToast(p.saved?"Saved to your memories.":"Removed from memories.")}if(e.target.closest(".edit-action")){const r=prompt("Edit your post:",p.text);if(r!==null&&r.trim()){p.text=r.trim();savePosts();renderFeed();showToast("Post updated.")}}if(e.target.closest(".delete-action")&&confirm("Delete this post?")){posts=posts.filter(i=>i.id!==a.dataset.id);savePosts();renderFeed();showToast("Post deleted.")}});
$("#genericView").addEventListener("change",e=>{if(e.target.id==="calendarMonth")$("#genericView").innerHTML=renderCalendar(e.target.value);if(e.target.id==="importData")importData(e.target.files[0])});
$("#genericView").addEventListener("click",e=>{if(e.target.id==="saveName"){const v=$("#displayName").value.trim();if(!v)return showToast("Please enter a name.");settings.name=v;settings.setupComplete=true;saveSettings();updateIdentity();showToast("Name saved.")}if(e.target.id==="saveAliyahDate"){settings.aliyahDate=$("#aliyahDate").value;saveSettings();switchView("settings");showToast("Aliyah date saved.")}const theme=e.target.closest(".theme-option");if(theme){settings.theme=theme.dataset.theme;saveSettings();applyTheme();switchView("settings");showToast("Theme selected.");return}if(e.target.id==="saveJournalEntry")saveNewJournalEntry();const el=e.target.closest(".journal-entry");if(el&&e.target.closest(".journal-delete")&&confirm("Delete this journal entry?")){journalEntries=journalEntries.filter(i=>i.id!==el.dataset.journalId);saveJournal();switchView("journal");showToast("Journal entry deleted.")}if(el&&e.target.closest(".journal-edit")){const entry=journalEntries.find(i=>i.id===el.dataset.journalId);$("#journalTitle").value=entry.title||"";$("#journalBody").value=entry.body;editingJournalId=entry.id;$("#saveJournalEntry").textContent="Update journal entry";window.scrollTo({top:0,behavior:"smooth"})}const day=e.target.closest(".calendar-day[data-date]");if(day){const key=day.dataset.date;$("#genericView").innerHTML=renderCalendar(key.slice(0,7),key)}if(e.target.id==="savePin"){const pin=$("#pinSetting").value.trim();if(!/^\d{4,8}$/.test(pin))return showToast("Use 4–8 numbers.");settings.pin=pin;saveSettings();switchView("settings");showToast("Privacy PIN saved.")}if(e.target.id==="removePin"){settings.pin="";saveSettings();switchView("settings");showToast("Privacy PIN removed.")}if(e.target.id==="exportData")exportData();if(e.target.id==="resetData"&&confirm("Remove your aliyah posts, journal entries, name, and settings from this browser?")){Object.values(KEYS).forEach(k=>localStorage.removeItem(k));location.reload()}});
function saveNewJournalEntry(){const body=$("#journalBody").value.trim();if(!body)return showToast("Write something before saving.");const title=$("#journalTitle").value.trim(),now=new Date();if(editingJournalId){const entry=journalEntries.find(i=>i.id===editingJournalId);entry.title=title;entry.body=body;editingJournalId=""}else journalEntries.unshift({id:crypto.randomUUID(),title,body,createdAt:now.toISOString(),date:readableDate(now)});saveJournal();switchView("journal");showToast("Journal entry saved.")}
function exportData(){const data=JSON.stringify({app:"My Aliyah",exportedAt:new Date().toISOString(),settings,posts,journalEntries},null,2),url=URL.createObjectURL(new Blob([data],{type:"application/json"})),link=document.createElement("a");link.href=url;link.download=`my-aliyah-backup-${new Date().toISOString().slice(0,10)}.json`;link.click();URL.revokeObjectURL(url);showToast("Backup downloaded.")}
function importData(file){if(!file)return;const r=new FileReader();r.onload=()=>{try{const d=JSON.parse(r.result);if(!Array.isArray(d.posts)||!Array.isArray(d.journalEntries))throw new Error();posts=d.posts;journalEntries=d.journalEntries;settings={...defaults,...(d.settings||{})};savePosts();saveJournal();saveSettings();applyTheme();switchView("settings");showToast("Backup restored.")}catch{showToast("That backup file is not valid.")}};r.readAsText(file)}
document.querySelectorAll(".nav-item").forEach(b=>b.addEventListener("click",()=>switchView(b.dataset.view)));$("#menuButton").addEventListener("click",()=>$(".sidebar").classList.toggle("open"));
function showSetup(){const b=document.createElement("div");b.className="modal-backdrop";b.innerHTML=`<div class="modal setup-modal" role="dialog" aria-modal="true" aria-labelledby="setupTitle"><p class="eyebrow">Welcome to My Aliyah</p><h2 id="setupTitle">What should we call you?</h2><p>Your name stays in this browser and can be changed anytime.</p><input id="setupName" maxlength="50" placeholder="Your name"><button id="finishSetup" class="primary-button">Begin my journey</button></div>`;document.body.appendChild(b);$("#setupName").focus();$("#finishSetup",b).addEventListener("click",()=>{const v=$("#setupName",b).value.trim();if(!v)return;settings.name=v;settings.setupComplete=true;saveSettings();b.remove();renderFeed();updateIdentity()})}
function showLock(){const s=document.createElement("div");s.className="lock-screen";s.innerHTML=`<div class="lock-card card"><p class="eyebrow">My Aliyah</p><h1>Your aliyah journal</h1><p>Enter your PIN to continue.</p><input id="unlockPin" class="pin-input" type="password" inputmode="numeric" maxlength="8" autocomplete="off"><button id="unlockButton" class="primary-button">Unlock</button><p id="lockError" aria-live="polite"></p></div>`;document.body.appendChild(s);const unlock=()=>{if($("#unlockPin").value===settings.pin)s.remove();else $("#lockError").textContent="That PIN is not correct."};$("#unlockButton").addEventListener("click",unlock);$("#unlockPin").addEventListener("keydown",e=>{if(e.key==="Enter")unlock()});$("#unlockPin").focus()}
applyTheme();renderFeed();updateIdentity();if(!settings.setupComplete)showSetup();else if(settings.pin)showLock();
